#!/usr/bin/env python3
"""Convert a binary file into a C byte array (portable fallback for bin_to_c.ps1).

Usage: bin_to_c.py <input> <output> <var_name>
Produces:
    const unsigned char <var_name>[N] = { 0x.., ... };
    const size_t <var_name>_size = N;
"""
import sys

def main():
    if len(sys.argv) != 4:
        sys.stderr.write("usage: bin_to_c.py <input> <output> <var_name>\n")
        return 2
    inp, outp, var = sys.argv[1], sys.argv[2], sys.argv[3]
    with open(inp, "rb") as f:
        data = f.read()
    n = len(data)
    lines = []
    lines.append("/* Auto-generated by third_party/icu/bin_to_c.py - DO NOT EDIT */")
    lines.append("#include <stddef.h>")
    lines.append("")
    lines.append("const unsigned char %s[%d] = {" % (var, n))
    chunk = []
    for i, b in enumerate(data):
        chunk.append("0x%02X" % b)
        if len(chunk) == 16:
            lines.append("  " + ", ".join(chunk) + ",")
            chunk = []
    if chunk:
        lines.append("  " + ", ".join(chunk))
    lines.append("};")
    lines.append("const size_t %s_size = %d;" % (var, n))
    lines.append("")
    with open(outp, "w") as f:
        f.write("\n".join(lines))
    sys.stderr.write("generated %s (%d bytes)\n" % (outp, n))
    return 0

if __name__ == "__main__":
    sys.exit(main())
